def _copy_settings() -> None:
    """Copia profili e orari dalla tabella settings (chiavi profilo:<utente> e orario:<utente> della release
    precedente). Gli orari uguali diventano una sola articolazione, condivisa. Le righe di settings restano (le
    migrazioni aggiungono): si tolgono in una release successiva."""
    import json
    from datetime import date, datetime, time, timezone

    conn = op.get_bind()
    now = datetime.now(timezone.utc)
    users = [r[0] for r in conn.execute(sa.text("select id from users order by id"))]
    rows = dict(conn.execute(sa.text(
        "select key, value from settings where key like 'profilo:%' or key like 'orario:%'"
    )).all())

    def ensure_profile(uid: int, prof: dict) -> None:
        conn.execute(
            sa.text("insert into profiles (user_id, full_name, employee_number, updated_at) "
                    "values (:u, :n, :m, :t) on conflict (user_id) do nothing"),
            {"u": uid, "n": prof.get("full_name"), "m": prof.get("employee_number"), "t": now},
        )

    groups: dict[str, list[int]] = {}
    for uid in users:
        prof = json.loads(rows.get(f"profilo:{uid}") or "{}")
        if prof:
            ensure_profile(uid, prof)
            for i, email in enumerate(prof.get("contest_recipients") or []):
                conn.execute(
                    sa.text("insert into profile_recipients (user_id, email, position) values (:u, :e, :p)"),
                    {"u": uid, "e": email, "p": i},
                )
        versions = json.loads(rows.get(f"orario:{uid}") or "{}").get("versions") or []
        if versions:
            groups.setdefault(json.dumps(versions, sort_keys=True), []).append(uid)

    for n, (content, uids) in enumerate(groups.items(), 1):
        versions = sorted(json.loads(content), key=lambda v: v["valid_from"])
        sid = conn.execute(
            sa.text("insert into schedules (name, created_at) values (:n, :t) returning id"),
            {"n": f"Articolazione {n}", "t": now},
        ).scalar_one()
        for v in versions:
            vid = conn.execute(
                sa.text(
                    "insert into schedule_versions (schedule_id, valid_from, entry_from, entry_to, pause_from, "
                    "pause_to, pause_counted_min, pause_terminal_min, no_pause_after_min, no_pause_deduct_min) "
                    "values (:s, :vf, :ef, :et, :pf, :pt, :pc, :pm, :na, :nd) returning id"
                ),
                {
                    "s": sid, "vf": date.fromisoformat(v["valid_from"]),
                    "ef": time.fromisoformat(v.get("entry_from", "07:30:00")),
                    "et": time.fromisoformat(v.get("entry_to", "09:30:00")),
                    "pf": time.fromisoformat(v.get("pause_from", "12:15:00")),
                    "pt": time.fromisoformat(v.get("pause_to", "13:15:00")),
                    "pc": v.get("pause_counted_min", 30), "pm": v.get("pause_terminal_min", 15),
                    "na": v.get("no_pause_after_min", 360), "nd": v.get("no_pause_deduct_min", 30),
                },
            ).scalar_one()
            for weekday, d in (v.get("days") or {}).items():
                conn.execute(
                    sa.text("insert into schedule_days (version_id, weekday, due_min, pause) values (:v, :w, :d, :p)"),
                    {"v": vid, "w": int(weekday), "d": d["due_min"], "p": d.get("pause", True)},
                )
        for uid in uids:
            ensure_profile(uid, {})
            conn.execute(
                sa.text("insert into profile_schedules (user_id, schedule_id, valid_from) values (:u, :s, :vf)"),
                {"u": uid, "s": sid, "vf": date.fromisoformat(versions[0]["valid_from"])},
            )


